from taf.ul.ettf.logger import custom_logger
import threading


logger = custom_logger('TimerGuard')


class TimerGuard(object):
    def __init__(self, timeout_handler, seconds):
        self.timer = threading.Timer(seconds, timeout_handler)

    def __enter__(self):
        self.timer.start()
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.timer.cancel()
